mapper.select:
SELECT id, bote_session_id, knowledge_base_id, kg_session_id, tenant_id, user_id, created_time, updated_time
FROM bt_knowledge_graph_session_rel
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND bote_session_id = #{boteSessionId}
  AND knowledge_base_id = #{knowledgeBaseId}
  AND status_cd = '00A'
LIMIT 1
